  "track.storage.m.map.s.slowLaunch.cause": "A big list lives in SharedPreferences",
  "track.storage.m.map.s.slowLaunch.causeDetail": "The first get waits for a multi-MB preferences file to load.",
  "track.storage.m.map.s.slowLaunch.fix": "Move the list to Room (chapters H1, H4).",
  "track.storage.m.map.ctl.symptom.slowLaunch": "The app stutters on launch, sometimes an ANR",
  "track.storage.m.map.s.photoGone.title": "The profile photo is gone after reinstalling",
  "track.storage.m.map.s.photoGone.detail": "The user reinstalls; the photo is gone and was never in the gallery.",
  "track.storage.m.map.s.photoGone.cause": "The photo was in app-specific storage",
  "track.storage.m.map.s.photoGone.causeDetail": "filesDir is removed on uninstall and invisible to other apps.",
  "track.storage.m.map.s.photoGone.fix": "Save photos users want to keep through MediaStore (chapters H1, H8).",
  "track.storage.m.map.ctl.symptom.photoGone": "The profile photo is gone after reinstalling",
  "track.storage.m.map.s.halfFile.title": "Crash on launch: truncated JSON",
  "track.storage.m.map.s.halfFile.detail": "Some users crash on every launch until they reinstall.",
  "track.storage.m.map.s.halfFile.cause": "A file written in place, killed mid-write",
  "track.storage.m.map.s.halfFile.causeDetail": "FileOutputStream truncates on open; the kill leaves a half-written file.",
  "track.storage.m.map.s.halfFile.fix": "Write through AtomicFile (chapter H2).",
  "track.storage.m.map.ctl.symptom.halfFile": "Crash on launch: truncated JSON",
  "track.storage.m.map.s.cacheMissing.title": "FileNotFoundException for a downloaded file",
  "track.storage.m.map.s.cacheMissing.detail": "A results PDF downloaded last week suddenly will not open.",
  "track.storage.m.map.s.cacheMissing.cause": "The system cleared the cache",
  "track.storage.m.map.s.cacheMissing.causeDetail": "Files in cacheDir may be deleted when space runs low.",
  "track.storage.m.map.s.cacheMissing.fix": "Check the file exists before reading, download again if missing (chapter H2).",
  "track.storage.m.map.ctl.symptom.cacheMissing": "FileNotFoundException for a downloaded file",
  "track.storage.m.map.s.anrStop.title": "An ANR when leaving the Settings screen",
  "track.storage.m.map.s.anrStop.detail": "commit() was changed to apply() but ANRs remain, now when leaving the screen.",
  "track.storage.m.map.s.anrStop.cause": "Pending apply() writes block a lifecycle transition",
  "track.storage.m.map.s.anrStop.causeDetail": "The framework waits for apply() writes before the Activity changes state.",
  "track.storage.m.map.s.anrStop.fix": "Move to DataStore (chapter H3).",
  "track.storage.m.map.ctl.symptom.anrStop": "An ANR when leaving the Settings screen",
  "track.storage.m.map.s.multiDs.title": "IllegalStateException: several DataStores for one file",
