  "track.storage.m.map.s.multiDs.causeDetail": "Each screen creates its own DataStore.",
  "track.storage.m.map.s.multiDs.fix": "One instance for the whole app, declared at the top level (chapter H3).",
  "track.storage.m.map.ctl.symptom.multiDs": "IllegalStateException: several DataStores for one file",
