  "track.storage.m.map.s.staleList.detail": "The new booking only appears after pull-to-refresh.",
  "track.storage.m.map.s.staleList.cause": "A one-shot read instead of a Flow",
  "track.storage.m.map.s.staleList.causeDetail": "A suspend function returns a snapshot; later writes wake nobody.",
  "track.storage.m.map.s.staleList.fix": "Make the DAO function return a Flow (chapter H4).",
  "track.storage.m.map.ctl.symptom.staleList": "Booked, but the list does not show it",
  "track.storage.m.map.s.dupAppt.title": "One appointment under two doctors",
  "track.storage.m.map.s.dupAppt.detail": "Now and then the Overview screen counts one appointment too many.",
  "track.storage.m.map.s.dupAppt.cause": "Separate queries, no transaction",
  "track.storage.m.map.s.dupAppt.causeDetail": "Sync writes between the N+1 loop's queries.",
  "track.storage.m.map.s.dupAppt.fix": "@Relation with @Transaction, or a JOIN returning a Map (chapter H5).",
  "track.storage.m.map.ctl.symptom.dupAppt": "One appointment under two doctors",
  "track.storage.m.map.s.crashUpdate.title": "Crashes on every launch after an update",
  "track.storage.m.map.s.crashUpdate.detail": "Only long-time users are hit; team devices work fine.",
  "track.storage.m.map.s.crashUpdate.cause": "A missing migration path",
  "track.storage.m.map.s.crashUpdate.causeDetail": "Users skip versions; Room throws IllegalStateException.",
  "track.storage.m.map.s.crashUpdate.fix": "Migrations for every version, with tests (chapter H6).",
